public String encodeCharacter(char[] immune, Character c) {
    // Defensive null checks
    if (c == null) {
        // Nothing to encode – return empty string to avoid NPE
        return "";
    }

    // If caller supplied immune characters, honor them
    if (immune != null && containsCharacter(c.charValue(), immune)) {
        return String.valueOf(c.charValue());
    }

    // Standard unencoded characters (alphanumeric etc.)
    if (UNENCODED_SET.contains(c)) {
        return String.valueOf(c.charValue());
    }

    // Convert the character to UTF‑8 bytes and percent‑encode each byte
    byte[] bytes = toUtf8Bytes(String.valueOf(c.charValue()));
    StringBuilder sb = new StringBuilder(bytes.length * 3);
    for (byte b : bytes) {
        appendTwoUpperHex(sb.append('%'), b);
