/**
 * Secure implementation of an Atom provider.
 *
 * The {@code readFrom} method has been hardened against XML External Entity (XXE)
 * attacks.  A fresh {@link Parser} instance is created for each request and
 * parser options are configured **before** parsing begins.  The options
 * explicitly disable entity resolution and enforce charset autodetection based on
 * the provider's configuration.  By avoiding shared mutable parser state and
 * applying the security settings outside of any synchronized block we guarantee
 * that the parser cannot be tricked into expanding external entities.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // other methods ...

    @Override
    public T readFrom(Class<T> clazz,
                      Type genericType,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a fresh parser for this request – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Configure parser options securely before parsing.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disallow resolution of external entities to prevent XXE.
        options.setResolveEntities(false);

        // Parse the input using the pre‑configured options.
        Document<T> doc = parser.parse(entityStream, options);

        // Return the root element of the parsed Atom document.
