     * Allocates a file inside {@code dir} using the supplied {@code name}.
     * <p>
     * The method sanitises {@code name} to prevent directory‑traversal attacks.
     * It normalises the resolved path and guarantees that the resulting file
     * resides within {@code dir}. If the target already exists, a numeric suffix
     * is added (e.g. {@code file-2.txt}) until a free name is found.
     *
     * @param dir  the base directory – must not be {@code null}
     * @param name the requested file name – must not be {@code null}
     * @return a {@link File} object that points to a non‑existing file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if {@code name} would escape {@code dir}
     * @throws IllegalStateException    if the required directories cannot be created
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        /* ---- 1. Strip optional query part (e.g. "file.txt?foo=bar") ---- */
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        /* ---- 2. Remove leading separators to avoid absolute paths ---- */
        while (!name.isEmpty() && (name.charAt(0) == '/' || name.charAt(0) == '\\')) {
            name = name.substring(1);
        }

        /* ---- 3. Resolve and normalise the target path ---- */
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        /* ---- 4. Verify that the resolved path is still inside {@code dir} ---- */
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                    "Invalid file name: path traversal detected (\""
                            + name + "\")");
        }

        /* ---- 5. Prepare for conflict‑resolution (duplicate file names) ---- */
        Path parent = targetPath.getParent();               // guaranteed non‑null
        String fileName = targetPath.getFileName().toString();

        int dot = fileName.indexOf('.');
        String prefix = (dot < 0) ? fileName : fileName.substring(0, dot);
        String suffix = (dot < 0) ? "" : fileName.substring(dot);
        int index = 2;
        Path candidate = targetPath;

        while (Files.exists(candidate)) {
            String newName = prefix + "-" + index++ + suffix;
            candidate = parent.resolve(newName);
        }

        /* ---- 6. Ensure the parent directory exists ---- */
        try {
            Files.createDirectories(candidate.getParent());
        } catch (IOException e) {
            throw new IllegalStateException(
                    "Unable to create directories for file: " + candidate, e);
        }

        return candidate.toFile();
    }

