public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // -----------------------------------------------------------------------
    // Patched extractFile – protects against Zip‑Slip (directory traversal)
    // -----------------------------------------------------------------------
    protected void extractFile(final File srcF,
                              final File dir,
                              final InputStream compressedInputStream,
                              final String entryName,
                              final Date entryDate,
                              final boolean isDirectory,
                              final Integer mode,
                              String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the target file *before* any checks.
        final File targetFile = FileUtils.resolveFile(dir, entryName);

        // -------------------------------------------------------------------
        // 1.  Canonical‑path validation – ensure the resolved file stays inside
        //     the intended extraction directory.
        // -------------------------------------------------------------------
        Path canonicalDirPath   = dir.getCanonicalFile().toPath();
        Path canonicalTargetPath = targetFile.getCanonicalFile().toPath();

        if (!canonicalTargetPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException(
                    "Entry is outside of the target directory (entryName=" + entryName + ")");
        }

        // -------------------------------------------------------------------
        // 2.  Prevent overwriting an existing symbolic link with a regular file.
        // -------------------------------------------------------------------
        if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalTargetPath)) {
            throw new ArchiverException(
                    "Refusing to overwrite existing symbolic link with regular file (entryName=" + entryName + ")");
        }

        try {
            // ----------------------------------------------------------------
            // 3.  Respect the overwrite flag and modification time.
            // ----------------------------------------------------------------
            if (!isOverwrite() && targetFile.exists()
                    && targetFile.lastModified() >= entryDate.getTime()) {
                return; // nothing to do – newer file already present
            }

            // ----------------------------------------------------------------
            // 4.  Ensure parent directories exist.
            // ----------------------------------------------------------------
            final File parent = targetFile.getParentFile();
            if (parent != null) {
                parent.mkdirs();
            }

            // ----------------------------------------------------------------
            // 5.  Extract according to entry type.
            // ----------------------------------------------------------------
            if (!StringUtils.isEmpty(symlinkDestination)) {
                // Create a symbolic link – the destination itself is not
                // validated here because it is supplied by the archive
                // author; the link will be created inside the target dir.
                SymlinkUtils.createSymbolicLink(targetFile, new File(symlinkDestination));
            } else if (isDirectory) {
                targetFile.mkdirs();
            } else {
                // Regular file – use try‑with‑resources to guarantee closure.
                try (OutputStream out = new FileOutputStream(targetFile)) {
                    IOUtil.copy(compressedInputStream, out);
                }
            }

            // ----------------------------------------------------------------
            // 6.  Preserve timestamps.
            // ----------------------------------------------------------------
            targetFile.setLastModified(entryDate.getTime());

            // ----------------------------------------------------------------
            // 7.  Preserve POSIX permissions when required.
            // ----------------------------------------------------------------
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
                ArchiveEntryUtils.chmod(targetFile, mode);
            }
        } catch (final FileNotFoundException ex) {
            // Log the problem but do not abort the whole extraction process.
            getLogger().warn("Unable to expand to file " + targetFile.getPath(), ex);
        }
    }

