/**
 * Extends the sign of a JPEG Huffman decoded value.
 *
 * <p>The original implementation used a {@code while} loop that recomputed {@code vt}
 * on each iteration, which could lead to an infinite loop when {@code t} was
 * outside the expected range. The JPEG specification requires a simple sign‑extension
 * operation: if the value {@code v} is less than {@code 2^(t‑1)} then it represents a
 * negative number and must be adjusted by adding {@code (-1 << t) + 1}.
 *
 * <p>This patched version:
 * <ul>
 *   <li>Validates {@code t} (must be between 1 and 31 inclusive) to prevent illegal
 *       shift operations and to guarantee termination.</li>
 *   <li>Replaces the erroneous loop with a single conditional check, matching the
 *       intended algorithm and eliminating the possibility of an infinite loop.</li>
 *   <li>Throws {@link IllegalArgumentException} for out‑of‑range parameters, allowing
 *       callers to handle malformed input safely.</li>
 * </ul>
 *
 * @param v the value to be sign‑extended
 * @param t the number of bits that {@code v} originally occupies
 * @return the correctly sign‑extended integer
 * @throws IllegalArgumentException if {@code t} is not in the range [1,31]
 */
private int extend(int v, final int t) {
    // Validate bit length to avoid undefined shift behavior and infinite loops.
    if (t <= 0 || t > 31) {
        throw new IllegalArgumentException("Bit length 't' must be between 1 and 31 inclusive, but was: " + t);
    }

    // Threshold for determining if the value is negative.
    int vt = 1 << (t - 1);

    // Perform sign extension only when the value is below the threshold.
    if (v < vt) {
        v += (-1 << t) + 1;
    }

    return v;
