import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.regex.Pattern;

public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    // whitelist pattern for locale strings: language[_country[_variant]]
    private static final Pattern LOCALE_PATTERN = Pattern.compile("^[a-zA-Z]{2,3}(_[a-zA-Z]{2})?(_[a-zA-Z0-9]+)?$");

    // other methods ...

    /**
     * Creates a Locale object from the request param, which might
     * be already a Locale or a String. The input is validated against a
     * whitelist of allowed locale formats to prevent injection attacks.
     *
     * @param requestedLocale the parameter from the request
     * @return the Locale or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        Locale locale = null;

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString().trim();

            if (isValidLocaleString(localeStr)) {
                // LocalizedTextUtil already handles null default locale safely
                locale = LocalizedTextUtil.localeFromString(localeStr, null);
            } else {
                LOG.warn("Rejected invalid locale parameter: {}", sanitizeForLog(localeStr));
            }
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

    /**
     * Checks whether the supplied string conforms to the allowed locale pattern.
     *
     * @param localeStr the locale string to validate
     * @return {@code true} if the string matches the whitelist pattern
     */
    private boolean isValidLocaleString(String localeStr) {
        return localeStr != null && LOCALE_PATTERN.matcher(localeStr).matches();
    }

    /**
     * Sanitises a string that will be written to the log. Removes control
     * characters that could be used to manipulate log files.
     *
     * @param input the raw input
     * @return a safe representation for logging
     */
    private String sanitizeForLog(String input) {
        if (input == null) {
            return "";
        }
        // Replace line breaks, tabs and other control chars with a single space
        return input.replaceAll("[\\p{Cntrl}]", " ");
    }

    // other methods ...

}
