private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

    ArchiveEntry entry;
    while ((entry = supplier.getNextReadableEntry()) != null) {
        String rawName = entry.getName();
        if (rawName == null) {
            continue; // or throw
        }
        // Normalize separators
        rawName = rawName.replace('\\', '/');

        // Reject absolute paths
        if (rawName.startsWith("/") || rawName.matches("^[a-zA-Z]:.*")) {
            throw new IOException("Invalid entry name (absolute path): " + rawName);
        }

        // Normalize path to eliminate ".." and "." segments
        Path entryPath = Paths.get(rawName).normalize();

        // After normalization, reject traversal outside target
        if (entryPath.startsWith("..") || entryPath.isAbsolute()) {
            throw new IOException("Invalid entry name (path traversal): " + rawName);
        }

        File f = new File(targetDirectory, entryPath.toString());

        Path canonicalFile = f.getCanonicalFile().toPath();
        if (!canonicalFile.startsWith(canonicalTargetDir)) {
            throw new IOException("expanding " + rawName + " would create file outside of " + targetDirectory);
        }

        if (entry.isDirectory()) {
            Files.createDirectories(canonicalFile);
        } else {
            // Ensure parent directories exist
            Path parent = canonicalFile.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            try (OutputStream o = Files.newOutputStream(canonicalFile)) {
                writer.writeEntryDataTo(entry, o);
            }
        }
    }
}

