    // Entries that use a data descriptor are cached and read from the cache.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    // Size of the entry as declared in the local file header.
    final long csize = current.entry.getSize();

    // Defensive check – a STORED entry must have a non‑negative size.
    // If the size is missing or corrupted we treat the entry as finished.
    if (csize < 0) {
        return -1;
    }

    // If we have already read the declared number of bytes, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Refill the internal buffer only when it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);

        // Do not read more than the remaining bytes of the entry.
        long remaining = csize - current.bytesRead;
        if (remaining <= 0) {
            return -1;
        }
        int maxToRead = (int) Math.min(buf.capacity(), remaining);
        int l = in.read(buf.array(), 0, maxToRead);
