public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Secure XML parsing utilities
    // -------------------------------------------------------------------------

    /**
     * Creates a {@link DocumentBuilderFactory} that is configured to prevent
     * XML External Entity (XXE) processing.
     *
     * @return a securely configured {@code DocumentBuilderFactory}
     * @throws Exception if the factory cannot be configured
     */
    private static DocumentBuilderFactory newSecureDocumentBuilderFactory() throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // General security features
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // Restrict access to external DTDs / Schemas (Java 7+)
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        // Preserve namespace information for XPath evaluation
        dbf.setNamespaceAware(true);
        return dbf;
    }

    /**
     * Parses the supplied {@link InputStream} into a {@link Document} using a
     * securely configured {@link DocumentBuilderFactory}.
     *
     * @param is the XML input stream
     * @return the parsed {@code Document}
     * @throws Exception if parsing fails
     */
    private static Document parseSecureDocument(InputStream is) throws Exception {
        DocumentBuilderFactory dbf = newSecureDocumentBuilderFactory();
        DocumentBuilder builder = dbf.newDocumentBuilder();
        return builder.parse(is);
    }

    // -------------------------------------------------------------------------
    // Original logic (now hardened)
    // -------------------------------------------------------------------------

    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();
        Exception cause = null;

        // 1. Try the configured type conversion first (e.g., to Document)
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e; // remember the conversion failure for later
            }
        }

        // 2. If conversion did not yield a result, handle known body types securely
        if (answer == null) {
            if (body instanceof WrappedFile) {
                // Convert the wrapped file to an InputStream and parse it securely
                InputStream is = exchange.getContext().getTypeConverter()
                        .convertTo(InputStream.class, exchange, body);
                if (is != null) {
                    try (InputStream autoClose = is) {
                        answer = parseSecureDocument(autoClose);
                    }
                }
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext().getTypeConverter()
                        .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null; // preserve original behaviour for this edge case
                }
            } else if (body instanceof String) {
                // Parse the XML string securely
                byte[] bytes = ((String) body).getBytes(StandardCharsets.UTF_8);
                try (InputStream is = new ByteArrayInputStream(bytes)) {
                    answer = parseSecureDocument(is);
                }
            }
        }

        // 3. Fallback handling when no document type is configured
        if (type == null && answer == null) {
            answer = body; // return the raw body as‑is
        } else if (answer == null) {
            // Propagate the original conversion error or throw a clear exception
            if (cause != null) {
                throw cause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }

        return answer;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods (unchanged)
}
