     *         is less than, equal to, or greater than {@code toVersion}
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        // Normalise null inputs to an empty string – they will be interpreted as "0.0.0"
        String safeFrom = (fromVersion == null) ? "" : fromVersion.trim();
        String safeTo   = (toVersion == null)   ? "" : toVersion.trim();

