    private static final Set<Class<?>> ALLOWED_TYPES;
    static {
        Set<Class<?>> s = new HashSet<>();
        // primitive wrappers
        s.add(Boolean.class);
        s.add(Byte.class);
        s.add(Character.class);
        s.add(Short.class);
        s.add(Integer.class);
        s.add(Long.class);
        s.add(Float.class);
        s.add(Double.class);
