        s.add(java.time.LocalDateTime.class);
        s.add(java.time.Instant.class);
        // collection/map types – Fastjson will materialise them as
        // JSONArray/JSONObject which are safe containers
        s.add(java.util.List.class);
        s.add(java.util.Map.class);
