     */
    private static boolean isAllowedComponent(Class<?> clazz) {
        if (clazz.isPrimitive()) {
            return true; // primitives (int, long, …) are safe
        }
        if (ALLOWED_TYPES.contains(clazz)) {
            return true;
        }
