     * @param typeVariable      the type variable to resolve
     * @return the resolved {@link Type} or {@code null} if it cannot be resolved
     */
    private static Type resolveTypeVariable(Class<?> rawClass, Type[] actualTypeArgs, TypeVariable<?> typeVariable) {
        TypeVariable<?>[] vars = rawClass.getTypeParameters();
        for (int i = 0; i < vars.length; i++) {
            if (vars[i].getName().equals(typeVariable.getName())) {
                return actualTypeArgs[i];
            }
